{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. ... Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The introduction describes the current state of knowledge about cancer complexity and prior use of system dynamics methods, and explicitly notes the uncertainty/gap that the extent of application to cancer prevention and control has not been studied."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention. ... In a 2019 report, the National Academies of Sciences, Engineering, and Medicine argued that systems science methods could help illustrate the multilevel nature of cancer effects and costs to society and help cancer control efforts be more agile and adaptive [7]. The Journal of the National Cancer Institute published several reports calling for the use of complex, multilevel, or systems-focused approaches to advance the landscape of cancer prevention and control [1, 2, 10].",
      "reason": "The authors explain the importance and need for the review by describing barriers in cancer control, calls from major bodies for systems approaches, and the potential role of system dynamics to address these needs."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The authors acknowledge prior reviews in the broader field but state that application specifically to cancer prevention and control has not been studied, thereby explaining the need for this focused review in relation to existing reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "This review was conducted according to PRISMA (Preferred Reporting Items for Systematic Reviews and Meta-Analysis) 2020 guidelines [29] (S1 Appendix). Scholarly articles describing the development or application of system dynamics models for cancer prevention and control were identified, abstracted, and analyzed. ... The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "The review is a methods review of system dynamics modeling applications and did not assess intervention effects or health outcomes, so describing an intervention mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "The review focuses on methodological applications of system dynamics to cancer prevention and control rather than evaluating specific complex interventions or delivery contexts; no logic model for an intervention is applicable in this context."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "System dynamics modeling, which consists of diagramming and simulation approaches for understanding and managing such complexity, is being increasingly applied to cancer prevention and control, but the breadth, characteristics, and quality of these studies is not known. We searched PubMed, Scopus, APA PsycInfo, and eight peer-reviewed journals to identify cancer-related studies that used system dynamics modeling. A dual review process was used to determine eligibility. Included studies were assessed using quality criteria adapted from prior literature and mapped onto the cancer control continuum. Characteristics of studies and models were abstracted and qualitatively synthesized.",
      "reason": "The abstract explicitly states the review's aims (to identify the breadth, characteristics, and quality of system dynamics studies applied to cancer and to synthesize characteristics), but it does not present these objectives using a formal question-formulation framework (e.g., PICO or similar)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": \"The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.\",
      "reason": "The review is a methods review that did not assess intervention effects or health outcomes, so PICO-style planned comparisons for intervention effects do not apply."
    }
  ],
  "confidence": 80
}

